inline void TSM(const char*l,bool*v){ImGuiWindow*w=ImGui::GetCurrentWindow();if(w->SkipItems)return;ImGui::TextColored(ts,l);ImGui::SameLine(ImGui::GetContentRegionAvail().x-20);ImVec2 p=w->DC.CursorPos;float tw=40,th=16,kr=7;ImGuiID id=w->GetID(l);ImRect tb(p,ImVec2(p.x+tw,p.y+th));ImGui::ItemSize(ImVec2(tw+8,th),0);if(!ImGui::ItemAdd(tb,id))return;bool h,held;ImGui::ButtonBehavior(tb,id,&h,&held);if(held&&ImGui::IsMouseClicked(0,id))*v=!*v;ImU32 tc=*v?IM_COL32(17,140,248,200):IM_COL32(30,33,42,200),kc=*v?IM_COL32(255,255,255,255):IM_COL32(160,170,190,255);w->DrawList->AddRectFilled(tb.Min,tb.Max,tc,th*.5f);w->DrawList->AddRect(tb.Min,tb.Max,IM_COL32(255,255,255,30),th*.5f,0,1);w->DrawList->AddRectFilled(ImVec2(*v?p.x+tw-kr*2:p.x,p.y),ImVec2(*v?p.x+tw:p.x+kr*2,p.y+th),kc,kr);w->DrawList->AddCircleFilled(ImVec2(*v?p.x+tw-kr:p.x+kr,p.y+th*.5f),kr-1.5f,IM_COL32(255,255,255,255));}
inline bool MSM(const char*l,float*v,float mn,float mx,const char*f){ImGuiWindow*w=ImGui::GetCurrentWindow();if(w->SkipItems)return 0;ImGui::TextColored(ts,l);ImGui::SameLine(150);char b[32];ImFormatString(b,32,f,*v);ImVec2 vs=ImGui::CalcTextSize(b);ImGui::SameLine(ImGui::GetContentRegionAvail().x-vs.x);ImGui::TextColored(tm,b);ImVec2 p=w->DC.CursorPos;float aw=ImGui::GetContentRegionAvail().x,wh=12,th=3,kr=5;ImGuiID id=w->GetID(l);ImRect bb(p,ImVec2(p.x+aw,p.y+wh));ImGui::ItemSize(bb,0);if(!ImGui::ItemAdd(bb,id))return 0;bool h,held;ImGui::ButtonBehavior(bb,id,&h,&held);if(held){float mx2=ImGui::GetIO().MousePos.x;float n=std::clamp((mx2-(p.x+kr))/(aw-2*kr),0.f,1.f);*v=mn+n*(mx-mn);ImGui::MarkItemEdited(id);}float t=std::clamp((*v-mn)/(mx-mn),0.f,1.f);float cy=p.y+wh*.5f;w->DrawList->AddRectFilled(ImVec2(p.x,cy-th*.5f),ImVec2(p.x+aw,cy+th*.5f),IM_COL32(30,33,42,220),th*.5f);w->DrawList->AddRect(ImVec2(p.x,cy-th*.5f),ImVec2(p.x+aw,cy+th*.5f),IM_COL32(255,255,255,25),th*.5f,0,1);float gx=p.x+kr+t*(aw-2*kr);w->DrawList->AddRectFilled(ImVec2(p.x,cy-th*.5f),ImVec2(gx,cy+th*.5f),IM_COL32(17,140,248,255),th*.5f);w->DrawList->AddCircleFilled(ImVec2(gx,cy),kr,held||h?IM_COL32(64,165,255,255):IM_COL32(17,140,248,255),16);w->DrawList->AddCircleFilled(ImVec2(gx,cy),kr-1,IM_COL32(255,255,255,255),12);return held;}
inline void DCM(ImVec2 mn,ImVec2 mx,const char*t,ImU32 acc){ImDrawList*d=ImGui::GetWindowDrawList();d->AddRectFilled(mn,mx,IM_COL32(bgC.x*255,bgC.y*255,bgC.z*255,bgC.w*255),10);d->AddRect(mn,mx,IM_COL32(bc.x*255,bc.y*255,bc.z*255,bc.w*255),10,0,1);d->AddRectFilled(ImVec2(mn.x,mn.y),ImVec2(mx.x,mn.y+2),IM_COL32(acc>>24&255,acc>>16&255,acc>>8&255,100),10,ImDrawFlags_RoundCornersTop);ImVec2 ip=ImVec2(mn.x+12,mn.y+12);d->AddCircleFilled(ip,4,IM_COL32(acc>>24&255,acc>>16&255,acc>>8&255,255));d->AddText(ImVec2(mn.x+22,mn.y+9),IM_COL32(tm.x*255,tm.y*255,tm.z*255,tm.w*255),t);}
